import sys

def main():
    s, t = sys.stdin.read().split()[:2]
    m = len(t)
    prev = list(range(m + 1))
    for i in range(1, len(s) + 1):
        cur = [i] + [0] * m
        ch = s[i - 1]
        for j in range(1, m + 1):
            if ch == t[j - 1]:
                cur[j] = prev[j - 1]
            else:
                a = prev[j - 1]
                b = prev[j]
                c = cur[j - 1]
                if b < a:
                    a = b
                if c < a:
                    a = c
                cur[j] = a + 1
        prev = cur
    print(prev[m])

main()

