from functools import lru_cache

s, t = sys.stdin.read().split()[:2]
sys.setrecursionlimit(10000)

@lru_cache(maxsize=None)
def f(i, j):
    if i == len(s):
        return len(t) - j
    if j == len(t):
        return len(s) - i
    if s[i] == t[j]:
        return f(i + 1, j + 1)
    return 1 + min(f(i + 1, j + 1), f(i + 1, j), f(i, j + 1))

